import subprocess as ss,PySimpleGUI as sg,base64 as ba
from libretranslatepy import LibreTranslateAPI as p

ltmb=""

path="/".join(__file__.split("\\")[0:-1])
try:open(f"{path}/ltm.exe","r").close()
except:tfil=open(f"{path}/ltm.exe","wb");tfil.write(ba.b64decode(ltmb));tfil.close()

sg.theme("Default1")
mpath="""By default, the program run ./ltm.exe and download the default model if not exists. you can specify args like --model-file /path/to/model.gguf if you want."""
rdmd="Model already loaded."
sfld="""Model loaded. Now write your text, 
specify DestLang(ISO639-1) and press 'Translate' button. (More below)
You may have noticed button freezes window, and is NORMAL due to library limitations. LTEngine supports 49 languages, so translation may fail for unsupported languages."""

oner="""Model not responds.
Possible Reasons:
-Firewall prompt (Just press the button again)
-Invalid args (help: ./ltm.exe -h)
-Model is not Gemma3
-Multiple Model execution (If you don't want to play hide-and-seek with Task Manager, don't do this.)

To restart the model, press the button again."""
fdtl="""Translation failed.
Maybe unsupported language or invalid ISO639-1 code.

Supported languages:
en (English), sq (Albanian), ar (Arabic), az (Azerbaijani), eu (Basque), bn (Bengali), bg (Bulgarian), ca (Catalan), zh (Chinese), zt (Chinese-traditional), cs (Czech), da (Danish), nl (Dutch), eo (Esperanto), et (Estonian), fi (Finnish), fr (French), gl (Galician), de (German), el (Greek), he (Hebrew), hi (Hindi), hu (Hungarian), id (Indonesian), ga (Irish), it (Italian), ja (Japanese), ko (Korean), lv (Latvian), lt (Lithuanian), ms (Malay), nb (Norwegian), fa (Persian), pl (Polish), pt (Portuguese), pb (Portuguese (Brazil)), ro (Romanian), ru (Russian), sr (Serbian), sk (Slovak), sl (Slovenian), es (Spanish), sv (Swedish), tl (Tagalog), th (Thai), tr (Turkish), uk (Ukrainian), ur (Urdu), vi (Vietnamese)"""

def t(a,b):return p("http://localhost:5050").translate(a,"auto",b)

layout=[[sg.Button("Load Model",k=0),sg.Multiline(mpath,s=(86,2),no_scrollbar=1,k=1,font=("d2coding",8))],[sg.Multiline(no_scrollbar=1,k=2,s=(77,9))],[sg.Input(k=3,s=36),sg.Text("← DestLang(ex en) ↑ YourText"),sg.Button("Translate",k=4)],[sg.Multiline(no_scrollbar=1,k=5,s=(77,9))]]
wd=sg.Window("LTEngine GUI",layout,font=("d2coding",12,"bold"))
while 1:
 ev,va=wd.read()
 if ev==None:break
 if ev==0:
  if va[1] not in (None,"",mpath,sfld):
   try:t("ok","en");wd[0].update(disabled=True);wd[1].update(sfld,disabled=True)
   except:
    try:sp=ss.Popen([f"{path}/ltm.exe"]+va[1].replace("\\","/").replace("'","").replace('"','').split(),shell=True);t("ok","en");wd[1].update(sfld,disabled=True);wd[0].update(disabled=True);wd[5].update("")
    except:wd[5].update(oner)
  else:
   try:t("ok","en");wd[0].update(disabled=True);wd[1].update(sfld,disabled=True)
   except:
    try:sp=ss.Popen(f"{path}/ltm.exe",shell=True);t("ok","en");wd[2].update("");wd[1].update(sfld,disabled=True);wd[0].update(disabled=True);wd[5].update("")
    except:wd[5].update(oner)
 if ev==4:
  j=va[2]
  try:
   for i in va[3].split():j=t(j,i);wd[5].update(j)
  except:wd[5].update(fdtl)


try:sp.kill()
except:print()
wd.close()